 const table=document.querySelector('#table').getBoundingClientRect();for(const item of group){const created=!motionTimes.has(item.key);if(created)motionTimes.set(item.key,item.newCard?now+item.delay:now-duration-1);const elapsed=now-motionTimes.get(item.key);if(elapsed>=item.duration||window.matchMedia('(prefers-reduced-motion: reduce)').matches)continue;const box=item.el.getBoundingClientRect(),scale=box.width/(item.el.offsetWidth||box.width);item.el.style.setProperty('--deal-x',((table.x+table.width/2-box.x-box.width/2)/scale)+'px');item.el.style.setProperty('--deal-y',((table.y+table.height/2-box.y-box.height/2)/scale)+'px');item.el.style.setProperty('--deal-duration',item.duration+'ms');item.el.style.animationDelay=(-elapsed)+'ms';item.el.classList.add('dealing');const animation=item.el.getAnimations().find(a=>a.animationName==='softDealFlip'),times=motionTimes;animation?.ready.then(()=>{if(motionTimes!==times)return;const delay=Number(animation.effect.getTiming().delay);if(!motionStarted.has(item.key)){times.set(item.key,Number(animation.startTime)+delay);motionStarted.add(item.key);}else animation.startTime=times.get(item.key)-delay;}).catch(()=>{});}
